45	    // Neither side runs `node --test` from here: nothing is duplicated.
46	    if (!pkgMatch && !verifyMatch) return [];
47	
48	    if (pkgMatch && !verifyMatch) {
49	      if (DELEGATES.test(verifyRaw)) return []; // single-sourced through `npm test`
